import { createContext, useCallback, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../state/reducers'
import { resetPolicyState, setPolicyState } from '../state/actions'

// this is the context used by the all pages
export const PolicyContext = createContext()

// provider provide the update context value
export const PolicyContextProvider = (props) => {
  // use reducer provides the initial state and dispatch function
  // to all nested children [state, dispatch]
  const [state, dispatch] = useReducer(reducer, INITIAL_STATE)

  const dispatchSetPolicyState = useCallback((payload) => dispatch(setPolicyState(payload)), [])
  const dispatchResetPolicyState = useCallback((payload) => dispatch(resetPolicyState(payload)), [])

  const ctxValue = [state, dispatch, dispatchSetPolicyState, dispatchResetPolicyState]
  return (
    <PolicyContext.Provider value={ctxValue}>
      {props.children}
    </PolicyContext.Provider>
  )
}

// use to read the value from the global state
export const usePolicyContextValue = () => useContext(PolicyContext)
