import { COMMON_ACTIONS } from '../../../../state/commonState/actions'
import { POLICY_ACTIONS } from './actions'

export const INITIAL_STATE = {
  packageType: 'car-protection-comprehensive', // default Selected
  transportationType: 'non-bus-non-truck', // default Data
  vehicleUse: 'Personal', // default Data
  manualFleetFormErrors: {},
}

const reducer = (state = INITIAL_STATE, action = {}) => {
  const { type, payload = {} } = action
  switch (type) {
    case POLICY_ACTIONS.GET_POLICY:
    case POLICY_ACTIONS.SUBMIT_POLICY:
    case POLICY_ACTIONS.GET_DOWNLOAD_PDF:
    case POLICY_ACTIONS.GET_DOWNLOAD_DRAFT_PDF:
    case POLICY_ACTIONS.GET_CITIES:
    case POLICY_ACTIONS.GET_PROVINCE:
    case POLICY_ACTIONS.GET_REGION_CODE:
    case POLICY_ACTIONS.GET_INSURANCE_DOCS:
    case POLICY_ACTIONS.UPDATE_QUOTATION:
    case POLICY_ACTIONS.GET_PACKAGES:
    case POLICY_ACTIONS.GET_PACKAGE_DETAIL:
    case POLICY_ACTIONS.CREATE_APPLICATION:
    case POLICY_ACTIONS.GET_POLICY_DETAIL:
    case POLICY_ACTIONS.UPDATE_APPLICATION:
    case POLICY_ACTIONS.GET_RENEWAL_ONE_TAP_DETAILS:
    case POLICY_ACTIONS.GET_MV_RENEWAL_DETAILS:
    case POLICY_ACTIONS.GET_TRANSACTION_SUMMARY:
    case POLICY_ACTIONS.POST_MV_RENEWAL_POLICY_OCR:
    case POLICY_ACTIONS.POST_DRAFT_POLICY_OCR:
    case POLICY_ACTIONS.RESET_POLICY_STATE:
    case POLICY_ACTIONS.GET_VARIANT_LIST:
    case POLICY_ACTIONS.GET_VARIANT_LIST_MV:
    case POLICY_ACTIONS.REMIND_CUSTOMER:
    case POLICY_ACTIONS.GET_MODEL_LIST:
    case POLICY_ACTIONS.GET_BRAND_LIST:
    case POLICY_ACTIONS.GET_BRAND_LIST_MV:
    case POLICY_ACTIONS.SET_POLICY_STATE:
    case POLICY_ACTIONS.GET_PROVIDER_LIST:
    case POLICY_ACTIONS.CREATE_OFFLINE_QUOTE:
    case POLICY_ACTIONS.SEND_DOCUMENT_EMAIL:
    case POLICY_ACTIONS.OFFLINE_QUOTE_DETAIL:
    case POLICY_ACTIONS.SUBMIT_APPLICATION:
    case POLICY_ACTIONS.SEND_PAYMENT_LINK:
    case POLICY_ACTIONS.UPDATE_POLICY_DISCOUNT:
    case POLICY_ACTIONS.UPDATE_OFFLINE_QUOTE_VEHICLE:
    case POLICY_ACTIONS.UPDATE_OFFLINE_QUOTE:
    case POLICY_ACTIONS.OFFLINE_QUOTE_ACCEPT:
    case POLICY_ACTIONS.CONVERT_DOC_TO_PDF:
    case POLICY_ACTIONS.VALIDATE_CHASSIS_NO:
    case POLICY_ACTIONS.CREATE_DRAFT_QUOTATION:
    case COMMON_ACTIONS.UPDATE_DRAFT_QUOTATION:
    case POLICY_ACTIONS.DRAFT_QUOTATIONS_DETAILS:
    case POLICY_ACTIONS.RESEND_PAYMENT_LINK:
    case POLICY_ACTIONS.UPDATE_EMAIL:
    case POLICY_ACTIONS.COMPLETE_DRAFT_QUOTE:
    case POLICY_ACTIONS.DRAFT_QUOTE_SEARCH:
    case POLICY_ACTIONS.GET_PAYMENT_STATUS:
    case POLICY_ACTIONS.GET_INSTALMENT_DETAILS:
    case POLICY_ACTIONS.GET_CONVERSION_RATE:
    case POLICY_ACTIONS.GET_ENDORSEMENT_REQ_FORM:
    case POLICY_ACTIONS.CREATE_ENDORSEMENT_REQ:
    case POLICY_ACTIONS.GET_OFFLINE_PRODUCT_FORM:
    case POLICY_ACTIONS.VALIDATE_POSTAL_CODE:
    case POLICY_ACTIONS.GET_PROPERTY_CONSTRUCTION:
    case POLICY_ACTIONS.GET_PROPERTY_OCCUPATION:
    case POLICY_ACTIONS.SHARE_DRAFT_QUOTE:
    case POLICY_ACTIONS.GET_CUSTOMER_DRAFT_QUOTE_DETAIL:
    case POLICY_ACTIONS.END_DATE_CALCULATION:
      return {
        ...state,
        ...payload,
      }
    case POLICY_ACTIONS.GET_VEHICLE_YEAR:
      return {
        ...state,
        getVehicleYearData: payload.getVehicleYearData?.reverse(),
      }
    case POLICY_ACTIONS.GET_RENEWAL_POLICY_LIST:
      return {
        ...state,
        getRenewalPolicyListData: {
          data: [
            ...(state.getRenewalPolicyListData?.data || []),
            ...(payload?.getRenewalPolicyListData.data || []),
          ],
          meta_data: payload?.getRenewalPolicyListData.meta_data,
        },
      }
    case POLICY_ACTIONS.GET_POLICY_LIST: {
      const isFirstPage = payload?.getPolicyListData?.meta_data?.page === 1
      return {
        ...state,
        getPolicyListData: [
          ...(isFirstPage ? [] : state.getPolicyListData || []),
          ...(payload?.getPolicyListData.data || []),
        ],
        getPolicyListMetaData: payload?.getPolicyListData.meta_data,
      }
    }
    case POLICY_ACTIONS.GET_POLICY_DRAFT_LIST: {
      const isFirstPage = payload?.getPolicyListData?.meta_data?.page === 1
      return {
        ...state,
        getPolicyDraftListData: [
          ...(isFirstPage ? [] : state.getPolicyDraftListData || []),
          ...(payload?.getPolicyDraftListData.data || []),
        ],
        getPolicyDraftListMetaData: payload?.getPolicyDraftListData.meta_data,
      }
    }
    case POLICY_ACTIONS.GET_POLICY_PAYMENT_PENDING_LIST: {
      const isFirstPage = payload?.getPolicyListData?.meta_data?.page === 1
      return {
        ...state,
        getPolicyPaymentPendingListData: [
          ...(isFirstPage ? [] : state.getPolicyPaymentPendingListData || []),
          ...(payload?.getPolicyPaymentPendingListData.data || []),
        ],
        getPolicyPaymentPendingListMetaData: payload?.getPolicyPaymentPendingListData.meta_data,
      }
    }
    case POLICY_ACTIONS.OFFLINE_QUOTE_LIST:
      return {
        ...state,
        offlineQuoteListData: [
          ...(state.offlineQuoteListData || []),
          ...(payload?.offlineQuoteListData.data || []),
        ],
        offlineQuoteListMetaData: payload?.offlineQuoteListData.meta_data,
      }
    case POLICY_ACTIONS.UPDATE_DISCOUNT:
      return {
        ...state,
        discount: payload,
      }
    case POLICY_ACTIONS.GET_CLAIMS_LIST:
      return {
        ...state,
        getClaimsListData: payload?.getClaimsListData,
      }
    default:
      return {
        ...(state || {}),
      }
  }
}

export default reducer
